-- ============================================================
-- Import & Distribute West Coast B2B Consultants Equally Across 4 Sales Reps
-- Total Leads: 296 (74 leads per salesperson)
-- Sales Team: Bourhane, Muiz, Walid, Hassan
-- ============================================================

-- 1. Fetch Sales Rep IDs into a temporary array
DO $$
DECLARE
  reps uuid[];
BEGIN
  SELECT array_agg(id ORDER BY email) INTO reps
  FROM public.profiles
  WHERE email IN (
    'bourhane.fetni7009@gmail.com',
    'muiziyiola75@gmail.com',
    'info@autoflowstudio.net',
    'hassansyhuzz@gmail.com'
  );

  -- If fewer than 4 specific emails found, fallback to any 4 profiles
  IF array_length(reps, 1) IS NULL OR array_length(reps, 1) < 4 THEN
    SELECT array_agg(id) INTO reps FROM (
      SELECT id FROM public.profiles LIMIT 4
    ) s;
  END IF;

  -- Insert 296 leads distributed round-robin (idx % 4)
END $$;

